{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_dict = {}
    children = {}
    for node in nodes:
        nid = node['id']
        node_dict[nid] = node
        children[nid] = []
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children[parent].append(node['id'])
    all_ids = list(node_dict.keys())
    sorted_ids = sorted(all_ids, key=lambda nid: (-node_dict[nid]['depth'], nid))
    retained = set(all_ids)
    removal_order = []
    for nid in sorted_ids:
        if nid not in retained:
            continue
        node = node_dict[nid]
        if nid == 'root' or node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        if any(cid in retained for cid in children[nid]):
            continue
        retained.remove(nid)
        removal_order.append(nid)
    retained_ids = sorted(retained)
    return {'retained_ids': retained_ids, 'removal_order': removal_order}"}
